sys_script_client.script:
function onSubmit() {

   //stores the value of the fields
	var checkone = g_form.getValue('x_1794838_cyberp_0_new_field_1');
	var checktwo = g_form.getValue('x_1794838_cyberp_0_checkbox_2');
	var checkthree = g_form.getValue('x_1794838_cyberp_0_checkbox_3');

	var counter = 0;
	var storevalue = [checkone,checktwo,checkthree];

	for (var i=0;i<storevalue.length;i++){
		if (storevalue[i] == 'true'){
			counter++;
		}
	}

	//if it smaller then 2 then error msg(from sys property) and terminate the client script
	if (counter<2){
		g_form.addErrorMessage('You have to select minimum two checkboxes');
		return false;
	}


}
